{
  id: 'M-DIVIS-01', stop: 'Jakautuuko tasan?', icon: '🔢',
  goal: 'Opit, mitä jaollinen tarkoittaa: luku jakautuu tasan ilman jakojäännöstä. Opit myös luvuilla 2, 5 ja 10 jaollisuuden tunnusmerkit.',
  intro: 'Verstaan laatikoihin pakataan tasan. Jos jotain jää yli, luku ei ole jaollinen.',
  reward: 'Tunnistat jaollisuuden ja sen merkit!',
  rev: AUDIT_REV, validRevs: [AUDIT_REV],
  demo: () => [
    { say: 'Kaksikymmentäneljä palloa pakataan laatikoihin, joihin mahtuu neljä. Kuusi täyttä laatikkoa, eikä mitään jää yli: kaksikymmentäneljä on jaollinen neljällä.', scene: packScene(24, 4) },
    { say: 'Yksi pallo lisää: kaksikymmentäviisi. Taas kuusi täyttä laatikkoa, mutta yksi pallo jää yli. Kaksikymmentäviisi ei ole jaollinen neljällä.', scene: packScene(25, 4) },
    { say: 'Loikka hyppii kaksi ruutua kerrallaan. Kaikki osumat päättyvät numeroon nolla, kaksi, neljä, kuusi tai kahdeksan. Siitä tunnistaa kahdella jaollisen.', scene: skipScene(2) },
    { say: 'Viiden hypyillä osumat päättyvät aina nollaan tai viiteen. Ja kymmenen hypyillä aina nollaan.', scene: skipScene(5) },
  ],
  item: cases({
    lastDigit: (r) => {
      const k = r.pick([2, 5, 10]), yes = r.chance(0.5);
      let n = r.int(21, 199);
      while ((n % k === 0) !== yes) n++;
      return {
        say: `Onko ${n} jaollinen luvulla ${k}?`,
        task: YESNO(yes, `Viimeinen numero on ${n % 10}, joten ${n} on jaollinen luvulla ${k}.`, `Viimeinen numero on ${n % 10}. Luvulla ${k} jaollinen päättyy ${k === 2 ? 'numeroon 0, 2, 4, 6 tai 8' : k === 5 ? 'numeroon 0 tai 5' : 'nollaan'}.`),
        hint: 'Katso viimeistä numeroa.',
        explain: yes ? `${n} : ${k} = ${n / k}, ei jää mitään.` : `${n} : ${k} = ${Math.floor(n / k)}, jää ${n % k}.`,
      };
    },
    threes: (r) => {
      const pool = r.shuffle(Array.from({ length: 30 }, (_, i) => i + 10));
      const yes = pool.filter((x) => x % 3 === 0).slice(0, 2 + r.int(0, 1)), no = pool.filter((x) => x % 3 !== 0).slice(0, 6 - yes.length);
      const opts = r.shuffle([...yes, ...no]);
      return {
        say: 'Valitse kaikki luvut, jotka ovat jaollisia luvulla 3.',
        task: { kind: 'multi', options: opts.map(n$), answer: opts.map((x, i) => (x % 3 === 0 ? i : -1)).filter((i) => i >= 0), cols: 3, why: opts.map((x) => (x % 3 ? `${x} : 3 = ${Math.floor(x / 3)}, jää ${x % 3}.` : `3 × ${x / 3} = ${x}.`)) },
        hint: 'Käy läpi kolmosen kertotaulu.',
        explain: `Jaollisia ovat ${opts.filter((x) => x % 3 === 0).sort((a, b) => a - b).join(', ')}: ne ovat kolmosen kertotaulussa.`,
      };
    },
    tags: (r) => {
      const pool = r.shuffle(Array.from({ length: 180 }, (_, i) => i + 11));
      const ten = pool.filter((x) => x % 10 === 0).slice(0, 2), five = pool.filter((x) => x % 5 === 0 && x % 10).slice(0, 2), two = pool.filter((x) => x % 2 === 0 && x % 10).slice(0, 2);
      const all = r.shuffle([...ten, ...five, ...two]);
      const cat = (x: number) => (x % 10 === 0 ? 0 : x % 5 === 0 ? 1 : 2);
      return {
        say: 'Lajittele luvut. Mihin laatikkoon kukin kuuluu?',
        task: {
          kind: 'sort' as const,
          items: all.map((x) => ({ big: String(x) })),
          cats: [{ label: 'jaollinen 10:llä' }, { label: 'jaollinen 5:llä, ei 10:llä' }, { label: 'jaollinen 2:lla, ei 5:llä' }],
          answer: all.map(cat),
          why: all.map((x) => `${x} päättyy numeroon ${x % 10}: ${x % 10 === 0 ? 'nolla, joten jaollinen 10:llä (ja myös 2:lla ja 5:llä).' : x % 5 === 0 ? 'viisi, joten jaollinen 5:llä mutta ei 10:llä.' : 'parillinen mutta ei 0 tai 5, joten jaollinen vain 2:lla.'}`),
        },
        hint: 'Katso jokaisen luvun viimeistä numeroa: 0, 5 vai parillinen?',
        explain: `Nollaan päättyvät jakautuvat 10:llä, viitoseen päättyvät 5:llä, muut parilliset vain 2:lla.`,
      };
    },
    meaning: (r) => {
      const k = r.int(3, 6), q = r.int(4, 9), yes = r.chance(0.5), n = k * q + (yes ? 0 : r.int(1, k - 1));
      return {
        say: `Onko ${n} jaollinen luvulla ${k}?`,
        task: YESNO(yes, `${k} × ${q} = ${n}, joten mitään ei jää yli.`, `${k} × ${q} = ${k * q}, ja ${n - k * q} jää yli.`),
        hint: `Pakkaa ${k} kerrallaan: jääkö yhtään yli? Mieti ${k}:n kertotaulua.`,
        explain: yes ? `${n} : ${k} = ${q}, ei jakojäännöstä.` : `${n} : ${k} = ${q}, jakojäännös ${n - k * q}.`,
      };
    },
  }, (r) => {
    const k = r.pick([3, 4, 5]), yes = r.chance(0.5), n = k * r.int(5, 9) + (yes ? 0 : r.int(1, k - 1));
    return {
      say: `${n} sammakkoa menee veneisiin. Jokaiseen veneeseen mahtuu ${k}. Menevätkö kaikki veneet aivan täyteen?`,
      task: YESNO(yes, `${n} on jaollinen luvulla ${k}: ${n} : ${k} = ${n / k}.`, `${n} ei ole jaollinen luvulla ${k}: yksi vene jää vajaaksi.`),
      hint: `Täyttyvätkö veneet tasan? Onko ${n} ${k}:n kertotaulussa?`,
      explain: yes ? `${n} : ${k} = ${n / k}. Kaikki veneet täyttyvät.` : `${n} : ${k} = ${Math.floor(n / k)}, ja ${n % k} jää yli. Viimeinen vene ei täyty.`,
    };
  }),
},
// ============================================================ order of operations

{
  id: 'M-MEAS-04', rev: AUDIT_REV, validRevs: [AUDIT_REV], stop: 'Mittaa yksiköllä', icon: '📐',
  goal: 'Opit mittaamaan pituuden toistamalla samaa yksikköä alusta loppuun ja kertomaan tuloksen luvulla ja yksiköllä.',
  intro: 'Lentopajan siipiin tarvitaan oikean pituisia rimoja. Mitataan ne yksiköllä.',
  reward: 'Mittaat pituuden yksiköllä, alusta loppuun!',
  demo: () => [
    { say: 'Pituus mitataan toistamalla samaa yksikköä: palat peräkkäin, ilman rakoja, alusta loppuun. Jokainen pala on yksi senttimetri. Viisi palaa: viisi senttimetriä.', scene: layScene(5) },
    { say: 'Viivoittimessa yksiköt ovat valmiina. Jos rima alkaa kohdasta kaksi, lasketaan välit kohdasta kaksi loppuun asti: kuusi senttiä.', scene: rulerScene(2, 8) },
    { say: 'Sama rima isommilla paloilla antaa pienemmän luvun. Siksi tulokseen kirjoitetaan aina yksikkö.', scene: twoUnitScene(6, 2) },
  ],
  item: cases({
    units: (r) => {
      const n = r.int(3, 9);
      return ask(`Jokainen keltainen pala on 1 cm. Kuinka pitkä rima on?`, n, `Paloja on ${n}, ja jokainen on 1 cm: ${n} cm.`, { unit: 'cm', scene: unitRow(n), hint: 'Laske palat rimaa pitkin alusta loppuun.', whyAt: { [n - 1]: 'Yksi pala jäi laskematta.', [n + 1]: 'Laskit yhden palan liikaa.' } });
    },
    offset: (r) => {
      const a = r.int(1, 4), len = r.int(3, 7), b = a + len;
      return ask('Kuinka monta senttimetriä rima on?', len, `Rima alkaa kohdasta ${a} ja loppuu kohtaan ${b}: välejä on ${len}, eli ${len} cm.`, { unit: 'cm', scene: rulerArt(12, a, b), hint: 'Rima ei ala nollasta. Laske välit.', whyAt: { [len + 1]: 'Laskit viivat, et välejä. Laske välit.', [b]: `${b} on riman loppukohta. Rima alkaa kohdasta ${a}, joten laske välit siitä.` } });
    },
    unitSize: (r) => {
      const big = r.pick([2, 3]), n = r.int(2, 4);
      return {
        say: `Loikka mittasi riman isoilla paloilla: ${word(n)} palaa. Aava mittaa saman riman pienillä paloilla. Saako Aava suuremman vai pienemmän luvun?`,
        scene: paint(unitRow(n, 24 * big, `${n} isoa palaa`) + unitRow(n * big, 24, `${n * big} pientä palaa`)),
        task: fixed([t('suuremman'), t('pienemmän'), t('saman')], 0, [undefined, 'Pieniä paloja mahtuu samaan pituuteen enemmän.', 'Luku riippuu siitä, kuinka iso yksikkö on.'], 3),
        hint: 'Kumpia paloja tarvitaan enemmän samaan pituuteen: isoja vai pieniä?',
        explain: `Pienempiä paloja tarvitaan enemmän: ${n * big} pientä palaa. Siksi tulokseen kirjoitetaan aina myös yksikkö.`,
      };
    },
  }, (r) => {
    const a = r.int(3, 6), len = r.int(4, 8), b = a + len;
    return {
      say: `Viivoittimen alkupää on katkennut. Rima on kohdasta ${a} kohtaan ${b}. Sulka sanoo: "Rima on ${b} cm." Kuinka pitkä rima on?`,
      scene: paint(rulerArt(14, a, b)),
      task: choose(r, t(`${len} cm`), [t(`${b} cm`), t(`${len + 1} cm`)], [`Riman pää on kohdassa ${b}, mutta alku ei ole nollassa.`, 'Laske välit, älä viivoja.']),
      hint: 'Loppukohta ei ole pituus, kun alku ei ole nollassa.',
      explain: `Välejä kohdasta ${a} kohtaan ${b} on ${len}: rima on ${len} cm.`,
    };
  }),
},

{
  id: 'M-MUL-01', rev: AUDIT_REV, validRevs: [AUDIT_REV], stop: 'Eväspussit', icon: '🎒',
  intro: 'Jokaiseen eväspussiin laitetaan yhtä monta.',
  reward: 'Pussit on pakattu tasan!',
  demo: (r) => [
    { say: 'Kolme pussia, ja jokaiseen laitetaan kaksi marjaa. Kaksi, neljä, kuusi. Kaksi plus kaksi plus kaksi on kuusi. Sama lyhyesti: kolme kertaa kaksi on kuusi.', scene: packScene('marja', 3, 2) },
    { say: 'Ensimmäinen luku kertoo, montako pussia. Toinen kertoo, montako jokaisessa pussissa. Neljä kertaa kolme: neljä pussia, jokaisessa kolme.', scene: packScene('simpukka', 4, 3) },
  ],
  item: cases({
    total: (r) => {
      const k = r.int(2, 4), g = r.int(2, 4), f = r.pick(FOOD);
      return {
        say: `Pusseja on ${word(k)}. Jokaisessa on ${word(g)} ${many(f, g)}. Montako on kaikkiaan?`,
        scene: paint(bagsArt(r, f, Array(k).fill(g))),
        task: (() => {
          const ws = [...new Set([k + g, k * g + g, k * g - 1])].filter((x) => x !== k * g).slice(0, 2);
          const why = (x: number) => x === k + g ? `Pussien määrää (${k}) ei lisätä yhden pussin määrään (${g}). Lasketaan kaikkien pussien sisällöt.` : x === k * g + g ? `Siinä on yksi pussi liikaa: pusseja on ${k}.` : 'Yksi jäi laskematta.';
          return choose(r, n$(k * g), ws.map(n$), ws.map(why));
        })(),
        hint: `Laske pussi kerrallaan: ${Array.from({ length: Math.min(k, 2) }, (_, i) => (i + 1) * g).join(', ')}, …`,
        explain: `${Array(k).fill(g).join(' + ')} = ${k * g}, eli ${k} × ${g} = ${k * g}.`,
      };
    },
    expr: (r) => {
      const k = r.int(2, 4), f = r.pick(FOOD); let g = r.int(2, 5); if (g === k) g = k + 1;
      const right = Array(k).fill(g).join(' + ');
      return {
        say: 'Mikä lasku sopii kuvaan?',
        scene: paint(bagsArt(r, f, Array(k).fill(g))),
        task: choose(r, txt(right), [txt(`${k} + ${g}`), txt(Array(k + 1).fill(g).join(' + '))], [`Pussien määrää ei lisätä pussin sisältöön. Jokaisen pussin ${g} lasketaan yhteen.`, `Siinä on ${k + 1} pussia, kuvassa vain ${k}.`], 1),
        hint: 'Jokaisesta pussista tulee laskuun yksi luku.',
        explain: `Pusseja on ${k}, jokaisessa ${g}: ${right}.`,
      };
    },
    pack: (r) => {
      const k = r.int(2, 4), g = r.int(2, 4), f = r.pick(FOOD);
      return {
        say: `Laita jokaiseen ${k === 2 ? 'kahteen' : k === 3 ? 'kolmeen' : 'neljään'} pussiin ${word(g)} ${many(f, g)}.`,
        task: { kind: 'pack' as const, k, g, thing: f },
        hint: `Napauta jokaista pussia ${g} kertaa.`,
        explain: `${Array(k).fill(g).join(' + ')} = ${k * g}, eli ${k} × ${g} = ${k * g}: ${k} pussia, jokaisessa ${g}.`,
      };
    },
    equal: (r) => {
      const k = 3, g = r.int(2, 4), f = r.pick(FOOD);
      const uneq = (): number[] => r.shuffle([g, g, g + r.pick([-1, 1])]);
      return { say: 'Missä kuvassa jokaisessa pussissa on yhtä monta?', hint: 'Laske jokaisen pussin sisältö ja vertaa.', task: choose(r, { art: bagsArt(r, f, Array(k).fill(g)) }, [{ art: bagsArt(r, f, uneq()) }, { art: bagsArt(r, f, uneq()) }], ['Näissä ei ole vielä yhtä monta.', 'Näissä ei ole vielä yhtä monta.'], 1), explain: `Oikeassa kuvassa jokaisessa pussissa on ${g}.` };
    },
  }, (r) => {
    const k = r.int(3, 4), g = r.int(2, 3), e = r.int(1, 3);
    return {
      say: `On ${word(k)} pussia, jokaisessa ${word(g)} marjaa. Lisäksi on ${e === 1 ? 'yksi irtomarja' : `${word(e)} irtomarjaa`}. Montako marjaa on kaikkiaan?`,
      task: choose(r, n$(k * g + e), [n$(k * g), n$(k * (g + e))], [`Irtomarjat puuttuvat.`, `Irtomarjat lisätään vain kerran, ei jokaiseen pussiin.`]),
      hint: 'Laske ensin pussit, lisää sitten irtomarjat.',
      explain: `${k} × ${g} = ${k * g}, ja vielä ${e}: ${k * g + e}.`,
    };
  }),
},

id: 'PHY79-NUMVALUE', rev: AUDIT_REV, validRevs: [AUDIT_REV], stop: 'Lukuarvo', icon: '🔢',
    goal: 'Opit erottamaan mittaustuloksesta lukuarvon: koko luvun, desimaaliosa mukaan lukien.',
    intro: 'Mittaustuloksessa on luku ja yksikkö. Erotetaan luku.',
    reward: 'Löydät lukuarvon mistä tahansa tuloksesta!',
    demo: () => [
      { say: 'Vaaka punnitsee: 2,5 kg. Tuloksen keskellä on lukuarvo 2,5. Se kertoo, kuinka paljon. Yksikkö kg kertoo, mihin verrattiin.', scene: measureScene('massa', 2.5, 'n') },
      { say: 'Merkinnässä s = 12,5 km on neljä osaa: tunnus s, yhtäsuuruusmerkki, lukuarvo 12,5 ja yksikkö km. Onko lukuarvo pelkkä 12? Ei, desimaaliosa kuuluu lukuun.', scene: partsScene([{ text: 's', role: 's' }, { text: '=' }, { text: '12,5', role: 'n' }, { text: 'km', role: 'u' }], { trap: '12', focus: 'n' }) },
    ],
    item: cases({
      plain: (r) => {
        const q = r.pick(QTYS); const v = r.pick(q.vals);
        return { say: `Mittaustulos on ${result(q, v)}. Mikä on lukuarvo?`, task: choose(r, t(fmt(v)), [t(q.unit), t(q.name)], [`${q.unit} on yksikkö: se kertoo, mihin verrattiin.`, `${q.name[0]!.toUpperCase() + q.name.slice(1)} on suure: se kertoo, mitä mitattiin.`]), hint: 'Lukuarvo on tuloksen luku.', explain: `Lukuarvo on ${fmt(v)}.` };
      },
      symbol: (r) => {
        const q = r.pick(QTYS); const v = r.pick(q.vals);
        return { say: `Merkintä ${q.sym} = ${result(q, v)}. Mikä on lukuarvo?`, task: choose(r, t(fmt(v)), [t(q.sym), t(q.unit)], [`${q.sym} on suureen ${q.name} tunnus, ei luku.`, `${q.unit} on yksikkö.`]), hint: 'Yhtäsuuruusmerkin jälkeen tulee ensin luku, sitten yksikkö.', explain: `${q.sym} on suureen tunnus, ${fmt(v)} lukuarvo ja ${q.unit} yksikkö.` };
      },
      type: (r) => {
        const q = r.pick(QTYS); const v = r.pick(q.vals.filter((x) => !Number.isInteger(x)).concat(q.vals.slice(0, 1)));
        const whyAt: Record<number, string> = {};
        if (!Number.isInteger(v)) whyAt[Math.floor(v)] = `Desimaaliosa kuuluu lukuarvoon: koko luku on ${fmt(v)}.`;
        return { ...ask(`Mittauksen tulos on ${q.sym} = ${result(q, v)}. Kirjoita pelkkä lukuarvo.`, v, '', `Lukuarvo on ${fmt(v)}; yksikkö ${q.unit} jää pois.`, undefined, 0.001), task: { kind: 'numeric', answer: v, tolerance: 0.001, whyAt }, hint: 'Kirjoita luku sellaisenaan, desimaaliosa mukaan lukien. Yksikköä ei kirjoiteta.' };
      },
      sort: (r) => {
        const [a, b] = r.shuffle(QTYS); const va = r.pick(a!.vals), vb = r.pick(b!.vals.filter((x) => x !== va));
        const all = r.shuffle([
          { v: fmt(va), c: 0, why: `${fmt(va)} on luku: lukuarvo.` }, { v: fmt(vb), c: 0, why: `${fmt(vb)} on luku: lukuarvo.` },
          { v: a!.unit, c: 1, why: `${a!.unit} on yksikkö.` }, { v: b!.unit, c: 1, why: `${b!.unit} on yksikkö.` }, { v: a!.name, c: 1, why: `${a!.name[0]!.toUpperCase() + a!.name.slice(1)} on suure.` },
        ]);
        return {
          say: `Tulokset: ${a!.name} ${result(a!, va)} ja ${b!.name} ${result(b!, vb)}. Lajittele palat: mitkä ovat lukuarvoja?`,
          task: { kind: 'sort' as const, items: all.map((x) => t(x.v)), cats: [{ label: 'Lukuarvo 🔢' }, { label: 'Muu osa' }], answer: all.map((x) => x.c), why: all.map((x) => x.why) },
          hint: 'Lukuarvo on luku. Yksikkö ja suure ovat sanoja tai merkkejä.',
          explain: `Lukuarvot ovat ${fmt(va)} ja ${fmt(vb)}.`,
        };
      },
    }, (r) => {
      const v = r.pick([0.25, 1.75, 12.5]);
      return { say: `Matka s = ${fmt(v)} km. Mikä on lukuarvo?`, task: choose(r, t(fmt(v)), [t(String(Math.floor(v))), t('km')], [`${Math.floor(v)} on vain kokonaisosa. Desimaaliosa kuuluu lukuarvoon.`, 'km on yksikkö.']), hint: 'Katso koko luku pilkun molemmin puolin.', explain: `Koko luku ${fmt(v)} on lukuarvo.` };
    }),
  },

id: 'PHY79-UNIT-CONCEPT', rev: AUDIT_REV, validRevs: [AUDIT_REV], stop: 'Yksikkö', icon: '📐',
    goal: 'Opit, että yksikkö kertoo, mihin mittausta verrattiin, eikä tulos ole valmis ilman sitä.',
    intro: 'Pelkkä luku ei kerro mittaustulosta. Mitä vielä tarvitaan?',
    reward: 'Yksiköt hallussa!',
    demo: () => [
      { say: 'Ensin piirretään 5 senttimetriä: pikkuruinen pätkä. Sitten 5 metriä, metri kerrallaan. Luku on sama, mutta pituudet ovat aivan eri. Metri on sata kertaa sentti.', scene: unitSizeScene(5, 'm', 'cm', 100, 'Pätkä') },
      { say: 'Merkinnässä t = 40 s yksikkö on s, sekunti. Se kertoo, että aikaa verrattiin sekuntiin. Ilman sitä 40 voisi olla minuutteja tai tunteja.', scene: partsScene([{ text: 't', role: 's' }, { text: '=' }, { text: '40', role: 'n' }, { text: 's', role: 'u' }], { focus: 'u' }) },
    ],
    item: cases({
      pick: (r) => {
        const q = r.pick(QTYS); const v = r.pick(q.vals);
        return { say: `Mikä on yksikkö tuloksessa ${result(q, v)}?`, task: choose(r, t(q.unit), [t(fmt(v)), t(q.name)], [`${fmt(v)} on lukuarvo: kuinka paljon.`, `${q.name[0]!.toUpperCase() + q.name.slice(1)} on suure: mitä mitattiin.`]), hint: 'Yksikkö tulee luvun perään.', explain: `Yksikkö on ${q.unit} (${q.unitName}).` };
      },
      fit: (r) => {
        const [q, ...rest] = r.shuffle(QTYS);
        const w = rest.slice(0, 2);
        return { say: `Millä yksiköllä ilmaistaan suure ${q!.name}?`, task: choose(r, t(q!.unit), w.map((x) => t(x.unit)), w.map((x) => `${x.unit} on suureen ${x.name} yksikkö.`)), hint: `Mitä ${q!.tool} näyttää?`, explain: `${q!.name}: ${q!.unit}.` };
      },
      fill: (r) => {
        const rows = r.shuffle(UNIT_FILL).slice(0, 3);
        const decoy = r.pick(UNIT_FILL.filter((x) => !rows.some((y) => y[2] === x[2])))!;
        return {
          say: 'Tuloksista puuttuvat yksiköt. Vedä jokaiseen järkevä yksikkö.',
          task: { kind: 'place', slots: rows.map((x, i) => ({ id: `s${i}`, text: `${x[0]}: ${x[1]} ▢` })), tokens: r.shuffle([...rows.map((x, i) => ({ id: `u${i}`, text: x[2] })), { id: 'x', text: decoy[2] }]), answer: Object.fromEntries(rows.map((_, i) => [`s${i}`, `u${i}`])), why: Object.fromEntries(rows.map((x, i) => [`s${i}`, x[3]])) } as Q['task'],
          hint: 'Mieti ensin suure: pituus, massa, aika vai lämpötila? Sitten järkevä koko.',
          explain: rows.map((x) => `${x[0]} ${x[1]} ${x[2]}`).join(', ') + '.',
        };
      },
    }, (r) => {
      const v = r.pick([120, 45, 8]);
      return { say: `Lassi kirjoitti: "Pöydän pituus on ${v}." Mitä tuloksesta puuttuu?`, task: choose(r, t('yksikkö'), [t('lukuarvo'), t('suure')], [`Lukuarvo ${v} on mukana.`, 'Suure (pituus) on mukana.']), hint: `Onko pöytä ${v} senttiä vai ${v} metriä? Mikä sen kertoisi?`, explain: `Ilman yksikköä ei tiedä, onko pöytä ${v} cm vai ${v} m.` };
    }),
  },

rawNodeSpec.rawNodeSpec:
{
    id: 'M-NUM-14', rev: AUDIT_REV, validRevs: [AUDIT_REV], stop: 'Mittausluku', icon: '📏',
    intro: 'Kun mittaat, luku kertoo, kuinka monta palaa pitkä esine on.',
    reward: 'Osaat kertoa mittauksen luvulla!',
    demo: () => [
      { say: 'Ladotaan palat ja lasketaan: yksi, kaksi, kolme, neljä, viisi, kuusi. Nauha on kuusi palaa pitkä. Kirjoitetaan: 6 palaa.', scene: layScene(6) },
      { say: 'Luku kertoo, montako palaa tarvittiin. Isoja paloja tarvitaan vähemmän: sama nauha on 6 pientä tai 3 isoa palaa.', scene: twoUnitScene(6, 2) },
    ],
    item: cases({
      read: (r) => {
        const n = r.int(2, 9), wr = near(r, n, 2, 1, 10);
        return {
          say: 'Mikä luku kertoo nauhan pituuden paloina?', scene: paint(unitsArt(n)),
          task: choose(r, num(n), wr.map(num), wr.map((m) => (m < n ? `${m} on liian vähän: osa paloista jäi laskematta.` : `${m} on liian monta: jokin pala tuli laskettua kahdesti.`))),
          hint: 'Laske palat nauhan alta.',
          explain: `Paloja on ${n}. Nauha on ${n} palaa pitkä.`,
        };
      },
      make: (r) => {
        const n = r.int(3, 8), wr = near(r, n, 2, 2, 9);
        return {
          say: `Missä nauha on ${word(n)} palaa pitkä?`,
          task: choose(r, { art: unitsArt(n) }, wr.map((m) => ({ art: unitsArt(m) })), wr.map((m) => `Tässä nauhassa on ${word(m)} palaa.`), 1),
          hint: 'Laske jokaisen nauhan palat.',
          explain: `Oikean nauhan alla on ${n} palaa.`,
        };
      },
      unit: (r) => {
        const small = r.pick([4, 6, 8]), big = small / 2;
        return {
          say: `Aava mittasi nauhan pienillä paloilla: ${word(small)} palaa. Loikka mittasi saman nauhan isoilla paloilla: ${word(big)} palaa. Kumman mittaama nauha on pidempi?`,
          scene: paint(twoUnitArt(small, 2)),
          task: fixed([{ text: 'Aavan', speak: 'Aavan' }, { text: 'Loikan', speak: 'Loikan' }, { text: 'Yhtä pitkä', speak: 'Yhtä pitkä' }], 2, [
            `${small} on isompi luku, mutta Aavan palat ovat pienempiä. Nauha on sama.`,
            'Loikan palat ovat isompia, mutta nauha on sama.',
          ]),
          hint: 'Mitattiinko kahta eri nauhaa vai samaa nauhaa?',
          explain: `Nauha on sama. Isoja paloja tarvittiin vähemmän kuin pieniä.`,
        };
      },
    }, (r) => {
      const a = r.int(3, 9), b = a + r.pick([-3, -2, 2, 3]);
      return {
        say: `Loikan keppi on ${word(a)} palaa pitkä. Aavan keppi on ${word(b)} palaa pitkä. Kumpi keppi on pidempi?`,
        task: fixed([{ text: 'Loikan', speak: 'Loikan' }, { text: 'Aavan', speak: 'Aavan' }], a > b ? 0 : 1, a > b ? [undefined, `Aavan keppi on vain ${word(b)} palaa.`] : [`Loikan keppi on vain ${word(a)} palaa.`]),
        hint: 'Kumpi keppi tarvitsi enemmän samankokoisia paloja?',
        explain: `${Math.max(a, b)} palaa on enemmän kuin ${Math.min(a, b)} palaa.`,
      };
    }),
  }

rawNodeSpec.transfer:
(r) => {
